{"command":"curl -s https://pub.dev/api/packages/js_widget_runtime | python3 -c "
import json,sys
d=json.load(sys.stdin)
v=d['latest']['version']
print('latest:', v)
for ver in [v,'0.4.175','0.4.172']:
    pub=d['versions'][-1]
    for pv in d['versions']:
        if pv['version']==ver:
            print(ver, 'sha256:', pv['archive_sha256'] if 'archive_sha256' in pv else pv.get('pubspec',{}).get('version'), pv['archive_url'][-40:] if 'archive_url' in pv else '')
" 2>&1 | head -20"}

